                        {{ $t("salaryItems.table.startdegree") }}
                      </th>
                      <th scope="col">{{ $t("salaryItems.table.created") }}</th>
                      <th scope="col">{{ $t("salaryItems.table.updated") }}</th>
                      <th scope="col">
