                      <td>{{ (page - 1) * limit + index + 1 }}</td>
                      <td>
                        {{
                          $i18n.locale == "ar" ? salary?.name : salary?.name_en
                        }}
                      </td>
                      <td>{{ salary.start_degree }}</td>
                      <td>{{ salary.created.split("T")[0] }}</td>
                      <td>{{ salary.updated.split("T")[0] }}</td>
                      <td>
                        <template
