                          $i18n.locale == "ar" ? item?.name : item?.name_en
                        }}</span>
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr
                      v-for="(salaryItemDegree, index) in salaryItemsDegrees"
