                            data-toggle="tooltip"
                            data-placement="top"
                            :title="
                              $i18n.locale == 'ar'
                                ? item?.salary_item?.name +
                                  ` ${basic_Salary_title} 2`
                                : item?.salary_item?.name_en +
                                  ` ${basic_Salary_title_en} 2`
                            "
                            type="number"
                            @change="
                              updatedSalaryItemBasicValue(
                                $event,
                                item,
                                2,
                                index + 1
                              )
                            "
                            :value="item?.value2"
                          />
                          <input
                            class="mx-2"
                            data-toggle="tooltip"
                            data-placement="top"
                            :title="
                              $i18n.locale == 'ar'
                                ? item?.salary_item?.name +
                                  ` ${basic_Salary_title} 3`
                                : item?.salary_item?.name_en +
